function validate([nums1, nums2]) {
  if (nums1.length < 2 || nums1.length > 100000) return 'nums1 needs 2 to 100000 values.';
  if (nums2.length !== nums1.length) return 'nums1 and nums2 must have the same length.';
  const inRange = v => Number.isInteger(v) && v >= 0 && v <= 200000;
  if (!nums1.every(inRange) || !nums2.every(inRange)) return 'Every value is an integer between 0 and 200000.';
  let keepOk = true, swapOk = true;
  for (let i = 1; i < nums1.length; i++) {
    const straight = nums1[i - 1] < nums1[i] && nums2[i - 1] < nums2[i];
    const crossed = nums1[i - 1] < nums2[i] && nums2[i - 1] < nums1[i];
    [keepOk, swapOk] = [(keepOk && straight) || (swapOk && crossed), (swapOk && straight) || (keepOk && crossed)];
  }
  if (!keepOk && !swapOk) return 'No set of swaps makes both arrays strictly increasing.';
  return null;
}

