function minSwap(nums1, nums2) {
  // Try every subset of indices to exchange and keep the smallest valid one.
  const n = nums1.length;
  let best = Infinity;
  for (let mask = 0; mask < (1 << n); mask++) {
    const a = nums1.map((v, i) => (mask >> i) & 1 ? nums2[i] : v);
    const b = nums2.map((v, i) => (mask >> i) & 1 ? nums1[i] : v);
    let ok = true;
    for (let i = 1; i < n && ok; i++) if (a[i - 1] >= a[i] || b[i - 1] >= b[i]) ok = false;
    if (!ok) continue;
    let moves = 0;
    for (let i = 0; i < n; i++) moves += (mask >> i) & 1;
    best = Math.min(best, moves);
  }
  return best;
}

