function generate(rand, size) {
  // Build two strictly increasing arrays, then exchange random positions so an answer always exists.
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 8);
  const step = size === 'large' ? 90 : 3;
  const a = [], b = [];
  let x = Math.floor(rand() * (size === 'large' ? 1000 : 4));
  let y = Math.floor(rand() * (size === 'large' ? 1000 : 4));
  for (let i = 0; i < n; i++) {
    a.push(x);
    b.push(y);
    x += 1 + Math.floor(rand() * step);
    y += 1 + Math.floor(rand() * step);
  }
  const flip = rand() * 0.8;
  for (let i = 0; i < n; i++) if (rand() < flip) [a[i], b[i]] = [b[i], a[i]];
  return [a, b];
}
